    """Draw inclusive straight panel-to-panel links between aligned equal marks."""
    h, w = len(grid), len(grid[0])
    sep_rows = {r for r, row in enumerate(grid) if all(v == 8 for v in row)}
    sep_cols = {c for c in range(w) if all(grid[r][c] == 8 for r in range(h))}

    def spans(size, separators):
        result = []
