        for i in range(size):
            if i in separators:
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < size:
            result.append((start, size))
        return result

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)
    marks = {}
    for ri, (r0, r1) in enumerate(row_spans):
